# Codice base della torre di guardia


func _ready() -> void:
	print("Torre di guardia pronta.")


func conta_lanterne_accese() -> int:
	var count: int = 0
	var lanterne: Array[Node] = get_tree().get_nodes_in_group("lanterne")
	for lanterna in lanterne:
		if "accesa" in lanterna and lanterna.accesa == true:
			count += 1
	return count


func spegni_tutte() -> void:
	get_tree().call_group("lanterne", "spegni")
